Lemma x2_mid : forall (RNG : footprint) (gp tp : word) (FR : bvmap 5 word) (fc : bv 32) (m3 : amem)
    (SPV SPA W FF DT S size flags mtl lo : Z) (junk : list byte)
    (y5 y6 y7 y15 y16 s4 s10 y28 y29 y30 y31 : word) (Q : machine_state -> Prop),
  mem_inv asegs m3 -> 0 <= SPA - 2224 -> SPA < 2^47 -> SPA <= SPV -> SPA mod 16 = 0 ->
  stk asegs m3 lo SPA -> lo <= SPA - 2208 -> KHIGH <= lo ->
  rt_got m3 -> rt_got_ric m3 -> rt_shbase m3 -> rt_inited m3 -> rt_layout m3 -> rt_real_mem m3 ->
  rw_cells asegs m3 (W + 624) [CB 112 junk] -> W + 624 + 112 <= lo ->
  app_blk (W + 624) (W + 624 + 112) -> unpoisoned m3 (W + 624) (W + 624 + 112) ->
  (hull_loR W <= W + 624 /\ W + 624 + 112 <= hull_hiR W 8704 /\ hull_loR W mod 64 = 0 /\ hull_hiR W 8704 mod 64 = 0
   /\ 0 <= hull_loR W /\ hull_hiR W 8704 <= KEND) ->
  wr_at asegs m3 (shad (hull_loR W)) (shad (hull_hiR W 8704) - shad (hull_loR W)) ->
  rng_aimg RNG -> rng RNG lo (SPA - lo) -> rng RNG (W + 624) 112 ->
  rng RNG (shad (hull_loR W)) (shad (hull_hiR W 8704) - shad (hull_loR W)) ->
  1 <= mtl <= 12 ->
  (forall m5 (z5 z6 z7 z28 z29 z30 z31 : word),
     munch [(SPA - 2208, SPA); (W + 624, W + 624 + 112)] m3 m5 -> wmono asegs m3 m5 -> mem_inv asegs m5 ->
     stk asegs m5 lo (SPA - 16) -> rw_cells asegs m5 (SPA - 16) [C8 (Z_to_bv 64 876); C8 (Z_to_bv 64 flags)] ->
     rw_cells asegs m5 (W + 624) [CB (Z.to_nat 112) (repeat (Z_to_bv 8 0) (Z.to_nat 112))] ->
     evtF asegs RNG Q
       (MS (mkR (Z_to_bv 64 0x816cc) (Z_to_bv 64 (SPA - 16)) gp tp z5 z6 z7 (Z_to_bv 64 SPV) (Z_to_bv 64 SPA)
                (Z_to_bv 64 (W + 992)) (Z_to_bv 64 256) (Z_to_bv 64 (W + 624)) (Z_to_bv 64 (FF + 48)) (Z_to_bv 64 (FF + 32))
                (Z_to_bv 64 S) (Z_to_bv 64 size) (Z_to_bv 64 (W + 1248))
                (Z_to_bv 64 S) (Z_to_bv 64 (W + 992)) (Z_to_bv 64 (FF + 32)) (Z_to_bv 64 (FF + 48)) (Z_to_bv 64 mtl)
                (Z_to_bv 64 size) (Z_to_bv 64 2147450880) (Z_to_bv 64 flags) (Z_to_bv 64 (-44)) (Z_to_bv 64 (W + 624))
                z28 z29 z30 z31)
           FR (Z_to_bv 64 0x95144) fc None m5 (seg_rom asegs))) ->
  evtF asegs RNG Q
    (MS (mkR (Z_to_bv 64 0x81674) (Z_to_bv 64 SPA) gp tp y5 y6 y7 (Z_to_bv 64 SPV) (Z_to_bv 64 SPA)
             (Z_to_bv 64 (W + 624)) (Z_to_bv 64 0) (Z_to_bv 64 112) (Z_to_bv 64 W)
             (Z_to_bv 64 (Z.shiftr DT 3 + 2147450880)) y15 y16 (Z_to_bv 64 (Z.shiftr FF 3 + 2147450880))
             (Z_to_bv 64 S) (Z_to_bv 64 FF) s4 (Z_to_bv 64 W) (Z_to_bv 64 mtl) (Z_to_bv 64 size) (Z_to_bv 64 2147450880)
             (Z_to_bv 64 flags) s10 (Z_to_bv 64 (W + 624)) y28 y29 y30 y31)
        FR (Z_to_bv 64 0x515b0) fc None m3 (seg_rom asegs)).
